// Onboarding — Step 2/4: Academic Profile
const { useState } = React;

function OnboardingScreen() {
  const [program, setProgram] = useState('Mercadotecnia');
  const [semester, setSemester] = useState(5);
  const [interests, setInterests] = useState(new Set(['Neurociencia computacional', 'Machine learning']));
  const [skill, setSkill] = useState('');
  const [skills, setSkills] = useState(['Python', 'Estadística R']);

  const toggleInterest = (i) => {
    const s = new Set(interests);
    s.has(i) ? s.delete(i) : s.add(i);
    setInterests(s);
  };
  const addSkill = (e) => {
    if (e.key === 'Enter' && skill.trim()) {
      setSkills([...skills, skill.trim()]); setSkill('');
      e.preventDefault();
    }
  };
  const removeSkill = (s) => setSkills(skills.filter(x => x !== s));

  return (
    <PhoneFrame theme="light">
      <div className="screen" style={{ paddingBottom: 120 }}>
        {/* Header region — surface-dim with network texture */}
        <div style={{ padding: '80px 24px 32px', background: 'var(--surface-dim)', position: 'relative', overflow: 'hidden' }}>
          <div style={{ position: 'absolute', inset: 0, backgroundImage: 'url(../../assets/network-pattern.svg)', backgroundSize: '160px 160px', color: 'var(--on-surface)', opacity: 0.08, pointerEvents: 'none' }}/>
          <div className="step-dots" style={{ marginBottom: 24, position: 'relative' }}>
            <div className="dot done"/><div className="dot active"/><div className="dot"/><div className="dot"/>
          </div>
          <div style={{ position: 'relative' }}>
            <div className="t-label-sm" style={{ color: 'var(--primary)', marginBottom: 8 }}>Paso 2 de 4 · Perfil académico</div>
            <h1 className="t-headline-lg" style={{ margin: 0, maxWidth: 280 }}>Cuéntanos sobre tu carrera</h1>
            <p className="t-body-md" style={{ margin: '12px 0 0', color: 'var(--on-surface-variant)', maxWidth: 300 }}>
              Esto nos ayuda a encontrar compañeros con objetivos académicos afines.
            </p>
          </div>
        </div>

        <div style={{ padding: 24, display: 'flex', flexDirection: 'column', gap: 20 }}>
          <div className="field">
            <label>Programa académico</label>
            <div className="input" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span>{program}</span>
              <Icon name="chevron-down" size={18} stroke={1.8}/>
            </div>
          </div>

          <div className="field">
            <label>Semestre</label>
            <div className="stepper">
              <span className="val">{semester}° semestre</span>
              <div style={{ display: 'flex', gap: 6 }}>
                <button onClick={() => setSemester(Math.max(1, semester - 1))}>−</button>
                <button onClick={() => setSemester(Math.min(12, semester + 1))}>+</button>
              </div>
            </div>
          </div>

          <div className="field">
            <label>Intereses de investigación · {interests.size} seleccionados</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {TRAMA_INTERESTS.map(i => (
                <Chip key={i} selected={interests.has(i)} onClick={() => toggleInterest(i)} size="sm">{i}</Chip>
              ))}
            </div>
          </div>

          <div className="field">
            <label>Habilidades</label>
            <div style={{ background: 'var(--surface-container-high)', borderRadius: 12, padding: 10, display: 'flex', flexWrap: 'wrap', gap: 6, alignItems: 'center' }}>
              {skills.map(s => (
                <span key={s} className="chip selected" style={{ fontSize: 12, padding: '6px 10px' }} onClick={() => removeSkill(s)}>
                  {s}  ×
                </span>
              ))}
              <input value={skill} onChange={e => setSkill(e.target.value)} onKeyDown={addSkill}
                placeholder="Agregar una habilidad…"
                style={{ flex: 1, minWidth: 140, background: 'transparent', border: 0, outline: 'none', font: '400 14px/1.3 Inter', color: 'var(--on-surface)', padding: '6px 4px' }}/>
            </div>
            <span className="t-body-sm">Enter para añadir</span>
          </div>
        </div>
      </div>

      {/* CTA bar — solid surface-container-low, not glass */}
      <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, padding: '16px 24px 28px', background: 'var(--surface-container-low)', zIndex: 40 }}>
        <button className="btn primary full">Continuar</button>
      </div>
    </PhoneFrame>
  );
}

const root = ReactDOM.createRoot(document.getElementById('app'));
root.render(<OnboardingScreen/>);

