/* Trama Campus — additions on top of ui_kit.css */

/* Phone variant: no bezel, designed to live inside design-canvas artboards */
.tc-phone {
  position: relative;
  width: 390px; height: 844px;
  background: var(--surface);
  color: var(--on-surface);
  font-family: var(--font-body);
  overflow: hidden;
  isolation: isolate;
  border-radius: 0;
}
.tc-phone .screen { background: var(--surface); }
.tc-phone .status-bar {
  position: absolute; top: 0; left: 0; right: 0; height: 44px;
  display: flex; justify-content: space-between; align-items: center;
  padding: 14px 24px 0;
  font: 600 14px/1 'Manrope'; color: var(--on-surface);
  font-feature-settings: "tnum"; z-index: 50; pointer-events: none;
}
.tc-phone .status-bar .icons { display: flex; gap: 6px; align-items: center; }
.tc-phone .status-bar .icons svg { width: 18px; height: 12px; color: var(--on-surface); }

/* Hero logo mark used in welcome / splash */
.tc-mark {
  width: 88px; height: 88px; border-radius: 24px;
  background: var(--gradient-cta);
  display: flex; align-items: center; justify-content: center;
  color: var(--on-primary);
  position: relative; overflow: hidden;
  box-shadow: var(--shadow-fab);
}
.tc-mark .glyph {
  font: 800 44px/1 'Manrope'; letter-spacing: -0.04em;
}
.tc-mark::after {
  content: ''; position: absolute; inset: 0;
  background-image:
    linear-gradient(60deg, rgba(255,255,255,0.07) 1px, transparent 1px),
    linear-gradient(120deg, rgba(255,255,255,0.07) 1px, transparent 1px),
    radial-gradient(circle at 25% 30%, rgba(255,255,255,0.18) 1.2px, transparent 2px);
  background-size: 22px 22px, 22px 22px, 28px 28px;
  pointer-events: none;
}
.tc-mark.sm { width: 44px; height: 44px; border-radius: 12px; }
.tc-mark.sm .glyph { font-size: 22px; }

/* Wordmark */
.tc-wordmark {
  font: 700 22px/1 'Manrope'; letter-spacing: -0.02em; color: var(--primary);
  display: inline-flex; align-items: center; gap: 8px;
}

/* Modality picker — onboarding */
.modality-card {
  background: var(--surface-container-lowest); border-radius: 24px;
  padding: 22px; cursor: pointer;
  display: grid; grid-template-columns: 48px 1fr auto; gap: 16px; align-items: center;
  transition: background .18s ease;
  border: 0;
  width: 100%; text-align: left;
  font-family: inherit; color: inherit;
  position: relative;
}
.modality-card:hover { background: var(--surface-bright); }
.modality-card .icn {
  width: 48px; height: 48px; border-radius: 14px;
  background: var(--secondary-container); color: var(--on-surface);
  display: flex; align-items: center; justify-content: center;
}
.modality-card .lbl { font: 600 17px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em; }
.modality-card .desc { font: 400 13px/1.4 'Inter'; color: var(--on-surface-variant); margin-top: 4px; }
.modality-card .check { width: 22px; height: 22px; border-radius: 9999px; border: 2px solid var(--outline-variant); }
.modality-card.selected { background: var(--surface-container-lowest); }
.modality-card.selected .icn { background: var(--gradient-cta); color: var(--on-primary); }
.modality-card.selected .check {
  border-color: var(--primary); background: var(--primary);
  display: flex; align-items: center; justify-content: center;
}
.modality-card.selected .check::after {
  content: ''; width: 8px; height: 4px; border: 2px solid var(--on-primary);
  border-top: 0; border-right: 0; transform: rotate(-45deg) translate(0, -1px);
}

/* University row (selection) */
.uni-row {
  display: grid; grid-template-columns: 44px 1fr auto; gap: 14px;
  padding: 14px 16px; border-radius: 16px;
  background: var(--surface-container-lowest); cursor: pointer; align-items: center;
  border: 0; width: 100%; text-align: left; font-family: inherit; color: inherit;
}
.uni-row + .uni-row { margin-top: 8px; }
.uni-row .crest {
  width: 44px; height: 44px; border-radius: 12px;
  background: var(--secondary-container); color: var(--on-surface);
  display: flex; align-items: center; justify-content: center;
  font: 700 14px/1 'Manrope'; letter-spacing: -0.01em;
}
.uni-row .uname { font: 600 15px/1.2 'Manrope'; color: var(--on-surface); }
.uni-row .uloc { font: 400 12px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 2px; }
.uni-row.disabled { opacity: 0.45; }
.uni-row .pill {
  font: 500 11px/1 'Inter'; padding: 6px 10px; border-radius: 9999px;
  background: var(--secondary-container); color: var(--on-surface-variant);
  letter-spacing: 0.2px;
}
.uni-row.selected { background: color-mix(in oklab, var(--primary) 8%, var(--surface-container-lowest)); }
.uni-row.selected .crest { background: var(--gradient-cta); color: var(--on-primary); }

/* Code input cells */
.code-cells {
  display: flex; gap: 10px; justify-content: center; margin: 24px 0 8px;
}
.code-cells .cell {
  width: 48px; height: 56px; border-radius: 12px;
  background: var(--surface-container-high); border: 0;
  font: 600 22px/1 'Manrope'; color: var(--on-surface);
  text-align: center; outline: none;
  font-feature-settings: "tnum";
}
.code-cells .cell.filled { background: var(--surface-container-lowest); box-shadow: inset 0 0 0 2px var(--primary); }

/* Compatibility breakdown — the editorial readout */
.compat-card {
  background: var(--surface-container-lowest);
  border-radius: 24px; padding: 22px;
  display: flex; flex-direction: column; gap: 18px;
}
.compat-card .h {
  font: 600 17px/1.2 'Manrope'; color: var(--on-surface); letter-spacing: -0.005em;
}
.compat-row { display: grid; grid-template-columns: 36px 1fr; gap: 14px; align-items: flex-start; }
.compat-row .icn {
  width: 36px; height: 36px; border-radius: 10px;
  background: var(--secondary-container); color: var(--on-surface);
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.compat-row.strong .icn { background: var(--gradient-cta); color: var(--on-primary); }
.compat-row .lab { font: 500 11px/1 'Inter'; color: var(--primary); letter-spacing: 0.4px; }
.compat-row .ttl { font: 600 14px/1.3 'Manrope'; color: var(--on-surface); margin-top: 5px; }
.compat-row .det { font: 400 13px/1.5 'Inter'; color: var(--on-surface-variant); margin-top: 4px; }
.compat-row .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.compat-card .divider { height: 1px; background: var(--outline-ghost); }

/* Discovery — feed (default) variant: large editorial cards */
.feed-card {
  background: var(--surface-container-lowest);
  border-radius: 24px; padding: 0;
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: background .18s ease;
}
.feed-card:hover { background: var(--surface-bright); }
.feed-card .ph {
  height: 220px;
  background: linear-gradient(160deg, var(--ph-from), var(--ph-to));
  position: relative;
}
.feed-card .ph .ctx-pill {
  position: absolute; top: 16px; left: 16px;
  padding: 7px 12px; border-radius: 9999px;
  background: var(--glass-bg); backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font: 500 11px/1 'Inter'; color: var(--on-surface);
  letter-spacing: 0.3px; display: inline-flex; gap: 6px; align-items: center;
}
.feed-card .ph .save {
  position: absolute; top: 14px; right: 14px;
  width: 36px; height: 36px; border-radius: 9999px;
  background: var(--glass-bg); backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  display: flex; align-items: center; justify-content: center;
  color: var(--on-surface); border: 0; cursor: pointer;
}
.feed-card .body { padding: 18px 20px 20px; display: flex; flex-direction: column; gap: 12px; }
.feed-card .row1 { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.feed-card .nm { font: 700 19px/1.15 'Manrope'; color: var(--on-surface); letter-spacing: -0.01em; }
.feed-card .meta { font: 400 13px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 4px; }
.feed-card .reasons { display: flex; flex-direction: column; gap: 8px; }
.feed-card .reason {
  display: grid; grid-template-columns: 18px 1fr; gap: 10px; align-items: flex-start;
  font: 400 13px/1.45 'Inter'; color: var(--on-surface);
}
.feed-card .reason .ic { color: var(--primary); margin-top: 2px; }
.feed-card .reason b { font-weight: 600; color: var(--on-surface); }
.feed-card .quote {
  font: 500 14px/1.5 'Manrope'; color: var(--on-surface);
  letter-spacing: -0.005em;
  padding: 12px 14px; border-radius: 14px;
  background: var(--surface-container-low);
}

/* Grid variant — compact, square */
.grid-feed { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 16px 24px; }
.grid-cell {
  position: relative; border-radius: 20px; overflow: hidden;
  aspect-ratio: 0.78;
  background: linear-gradient(160deg, var(--ph-from), var(--ph-to));
  cursor: pointer;
}
.grid-cell .gd-meta {
  position: absolute; left: 12px; right: 12px; bottom: 12px;
  padding: 10px 12px; border-radius: 12px;
  background: var(--glass-bg); backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--on-surface);
}
.grid-cell .gd-name { font: 600 14px/1.2 'Manrope'; letter-spacing: -0.005em; }
.grid-cell .gd-sub  { font: 400 11px/1.3 'Inter'; color: var(--on-surface-variant); margin-top: 2px; }
.grid-cell .gd-pill {
  position: absolute; top: 10px; left: 10px;
  padding: 5px 9px; border-radius: 9999px;
  background: var(--glass-bg); backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font: 500 10px/1 'Inter'; color: var(--primary); letter-spacing: 0.3px;
}

/* Stories variant — horizontal carousel of "context invitations" */
.stories-strip {
  display: flex; gap: 10px; overflow-x: auto; padding: 4px 24px 0;
  scrollbar-width: none;
}
.stories-strip::-webkit-scrollbar { display: none; }
.story-card {
  flex: 0 0 auto; width: 140px; height: 200px;
  border-radius: 22px; padding: 14px; position: relative;
  background: linear-gradient(160deg, var(--ph-from), var(--ph-to));
  display: flex; flex-direction: column; justify-content: flex-end;
  color: var(--on-surface); overflow: hidden; cursor: pointer;
}
.story-card .scrim {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.45) 100%);
}
.story-card .content { position: relative; }
