/* global React, ReactDOM */
// Trama Campus — shared components used across all screens.

const { useState, useEffect, useRef, useMemo } = React;

// --- Icon (Lucide) ---------------------------------------------------------
function TIcon({ name, size = 22, stroke = 1.5, color, style, ...rest }) {
  const ref = useRef(null);
  useEffect(() => {
    if (window.lucide && ref.current) {
      ref.current.setAttribute('data-lucide', name);
      ref.current.innerHTML = '';
      window.lucide.createIcons({
        nameAttr: 'data-lucide',
        attrs: { 'stroke-width': stroke, width: size, height: size },
        icons: window.lucide.icons,
        parent: ref.current.parentNode,
      });
    }
  }, [name, stroke, size]);
  return <i ref={ref} data-lucide={name} style={{ width: size, height: size, display: 'inline-flex', color, ...style }} {...rest} />;
}

// --- Phone (no bezel — for design-canvas artboards) -----------------------
function TPhone({ theme = 'light', children, statusBar = true }) {
  return (
    <div className="trama-root tc-phone" data-theme={theme}>
      {statusBar && (
        <div className="status-bar">
          <span>9:41</span>
          <span className="icons">
            <svg viewBox="0 0 18 12" fill="none"><path d="M1 10 L1 8 M4 10 L4 6 M7 10 L7 4 M10 10 L10 2" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
            <svg viewBox="0 0 18 12" fill="none"><path d="M2 2 Q9 -2 16 2 M4 5 Q9 2 14 5 M6 8 Q9 6 12 8" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" fill="none"/></svg>
            <svg viewBox="0 0 22 12" fill="none"><rect x="1" y="2" width="17" height="8" rx="2" stroke="currentColor" strokeWidth="1" fill="none"/><rect x="2.5" y="3.5" width="11" height="5" rx="1" fill="currentColor"/><rect x="19" y="5" width="2" height="2" rx="0.5" fill="currentColor"/></svg>
          </span>
        </div>
      )}
      {children}
    </div>
  );
}

// --- Brand mark (the orange hex in the logo) ------------------------------
function TramaMark({ size = 88 }) {
  return (
    <div className="tc-mark" style={{ width: size, height: size, borderRadius: size * 0.27 }}>
      <span className="glyph" style={{ fontSize: size * 0.5 }}>T</span>
    </div>
  );
}

// --- Bottom nav -----------------------------------------------------------
function TBottomNav({ active = 'discover' }) {
  const tabs = [
    { id: 'discover', icon: 'compass',     label: 'Descubrir' },
    { id: 'matches',  icon: 'users-round', label: 'Conexiones' },
    { id: 'chat',     icon: 'message-square', label: 'Chats' },
    { id: 'profile',  icon: 'user-round',  label: 'Perfil' },
  ];
  return (
    <nav className="bottom-nav">
      {tabs.map(t => (
        <button key={t.id} className={"tab" + (active === t.id ? ' active' : '')}>
          <TIcon name={t.icon} stroke={active === t.id ? 2 : 1.5} size={22}/>
          <span className="lbl">{t.label}</span>
        </button>
      ))}
    </nav>
  );
}

// --- Photo placeholder ----------------------------------------------------
function TPhoto({ hue = 30, name = '', children, style, className = '' }) {
  const initials = name ? name.split(' ').slice(0, 2).map(s => s[0]).join('').toUpperCase() : '';
  return (
    <div
      className={'photo-placeholder ' + className}
      style={{
        ...style,
        '--ph-from': `oklch(78% 0.06 ${hue})`,
        '--ph-to':   `oklch(50% 0.12 ${(hue+30)%360})`,
      }}
    >
      {initials && <div className="ph-init">{initials}</div>}
      {children}
    </div>
  );
}

// --- Avatar (circle with initials) ----------------------------------------
function TAvatar({ name = '', hue = 30, size = 48 }) {
  const initials = name.split(' ').slice(0,2).map(s => s[0]).join('').toUpperCase();
  return (
    <div className="avatar" style={{
      width: size, height: size, fontSize: size * 0.36,
      background: `linear-gradient(135deg, oklch(80% 0.05 ${hue}), oklch(58% 0.10 ${(hue+30)%360}))`,
      color: 'rgba(255,255,255,0.85)',
    }}>{initials}</div>
  );
}

// --- Chip -----------------------------------------------------------------
function TChip({ children, selected, onClick, size, variant }) {
  const cls = ['chip'];
  if (selected) cls.push('selected');
  if (variant === 'filter') cls.push('filter');
  if (variant === 'filter-active') cls.push('filter', 'active');
  if (size === 'sm') cls.push('small');
  return <button className={cls.join(' ')} onClick={onClick}>{children}</button>;
}

// --- Step dots ------------------------------------------------------------
function StepDots({ total, current }) {
  return (
    <div className="step-dots">
      {Array.from({ length: total }).map((_, i) => (
        <div key={i} className={"dot " + (i < current ? 'done' : i === current ? 'active' : '')}/>
      ))}
    </div>
  );
}

// --- App bar with title + bell --------------------------------------------
function TAppBar({ title, subtitle, modality, onModality, showBell = true, hasUnread = false, right }) {
  return (
    <div className="app-bar" style={{ paddingRight: 24 }}>
      <div className="row">
        <div style={{ flex: 1, minWidth: 0 }}>
          {subtitle && <div className="t-label-sm" style={{ color: 'var(--primary)', marginBottom: 4 }}>{subtitle}</div>}
          <div className="title" style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</div>
        </div>
        {right}
        {showBell && (
          <button className={"back" + (hasUnread ? ' bell-with-dot' : '')} aria-label="Notificaciones">
            <TIcon name="bell" size={18} stroke={1.8}/>
          </button>
        )}
      </div>
      {modality && (
        <div style={{ marginTop: 12 }}>
          <ModalityPills active={modality} onChange={onModality}/>
        </div>
      )}
    </div>
  );
}

// --- Modality pill row (top of Discovery) ---------------------------------
function ModalityPills({ active, onChange }) {
  return (
    <div className="modality-switch">
      {window.TRAMA_MODALITIES.map(m => (
        <button key={m.id} className={active === m.id ? 'on' : ''} onClick={() => onChange && onChange(m.id)}>
          <TIcon name={m.icon} size={14} stroke={1.8}/>
          {m.label}
        </button>
      ))}
    </div>
  );
}

// --- Compatibility Card ---------------------------------------------------
function CompatibilityCard({ student }) {
  const items = [
    { icon: 'graduation-cap', strong: student.sharedCourses.length > 0,
      label: 'Afinidad académica',
      title: student.sharedCourses.length ? `${student.sharedCourses.length} cursos en común` : 'Sin cursos en común',
      detail: student.sharedCourses.length ? null : 'Distinta facultad — el match viene por interés.',
      tags: student.sharedCourses,
    },
    { icon: 'microscope', strong: student.sharedInterests.length >= 2,
      label: 'Intereses compartidos',
      title: `${student.sharedInterests.length} intereses en común`,
      detail: null,
      tags: student.sharedInterests,
    },
    { icon: 'compass', strong: student.sharedGoals.length > 0,
      label: 'Metas similares',
      title: student.sharedGoals.length ? 'Buscan algo parecido este semestre' : 'Metas distintas',
      detail: student.sharedGoals.length ? null : 'No hay overlap directo, pero pueden complementarse.',
      tags: student.sharedGoals,
    },
  ];
  return (
    <div className="compat-card">
      <div className="h">Por qué se parecen</div>
      {items.map((it, i) => (
        <React.Fragment key={i}>
          {i > 0 && <div className="divider"/>}
          <div className={"compat-row" + (it.strong ? ' strong' : '')}>
            <div className="icn"><TIcon name={it.icon} size={18} stroke={1.8}/></div>
            <div>
              <div className="lab">{it.label}</div>
              <div className="ttl">{it.title}</div>
              {it.detail && <div className="det">{it.detail}</div>}
              {it.tags.length > 0 && (
                <div className="tags">
                  {it.tags.map(t => <TChip key={t} size="sm">{t}</TChip>)}
                </div>
              )}
            </div>
          </div>
        </React.Fragment>
      ))}
    </div>
  );
}

// --- Helper: feed card (editorial) ----------------------------------------
function FeedCard({ s, modality }) {
  const mod = window.TRAMA_MODALITIES.find(m => m.id === s.intent);
  const ctxText = s.sharedCourses[0]
    ? `Conectados vía ${s.sharedCourses[0]}`
    : s.sharedInterests[0]
      ? `Sugerido · ${s.sharedInterests[0]}`
      : 'Sugerido por intereses';
  return (
    <div className="feed-card">
      <TPhoto hue={s.hue} name={s.name} style={{ '--ph-from': `oklch(78% 0.06 ${s.hue})`, '--ph-to': `oklch(50% 0.12 ${(s.hue+30)%360})` }} className="ph">
        <div className="ph">
          <div className="ctx-pill">
            <TIcon name={mod ? mod.icon : 'compass'} size={12} stroke={2}/>
            {ctxText}
          </div>
          <button className="save" aria-label="Guardar"><TIcon name="bookmark" size={16} stroke={1.8}/></button>
          <div className="ph-init">{s.name.split(' ').slice(0,2).map(x=>x[0]).join('')}</div>
        </div>
      </TPhoto>
      <div className="body">
        <div className="row1">
          <div>
            <div className="nm">{s.name}, {s.age}</div>
            <div className="meta">{s.program} · {s.semester}° semestre</div>
          </div>
          <div className="stat-pill primary">
            <TIcon name={mod ? mod.icon : 'compass'} size={12} stroke={2}/>
            {mod ? mod.label : ''}
          </div>
        </div>
        <div className="reasons">
          {s.sharedCourses[0] && (
            <div className="reason">
              <span className="ic"><TIcon name="graduation-cap" size={16} stroke={1.8}/></span>
              <span>Comparten <b>{s.sharedCourses[0]}</b>{s.sharedCourses[1] ? ` y ${s.sharedCourses[1]}` : ''}.</span>
            </div>
          )}
          {s.sharedInterests[0] && (
            <div className="reason">
              <span className="ic"><TIcon name="microscope" size={16} stroke={1.8}/></span>
              <span>Coinciden en <b>{s.sharedInterests.slice(0,2).join(', ')}</b>.</span>
            </div>
          )}
          {s.sharedGoals[0] && (
            <div className="reason">
              <span className="ic"><TIcon name="compass" size={16} stroke={1.8}/></span>
              <span>Buscan: <b>{s.sharedGoals[0]}</b>.</span>
            </div>
          )}
        </div>
        <div className="quote">"{s.bio.length > 110 ? s.bio.slice(0, 110) + '…' : s.bio}"</div>
      </div>
    </div>
  );
}

