// Build a fully inline standalone HTML, no blobs.
// 1. Read the original index.html (not standalone — we'll do everything inline)
// 2. Inline all <link rel="stylesheet"> as <style>
// 3. Inline all <script src> (external CDN) by fetching... wait, sandbox can't fetch.
//    Instead: keep React/Babel/Lucide as external CDN URLs (these work from any host with internet)
//    OR: inline them by reading from a project file if we have copies.
// 4. Inline all local <script src="*.jsx|*.js"> by reading file contents
// 5. Replace all url(...) in CSS with data: URIs for assets
// 6. Replace asset references in JSX (already done via window.__resources)
//    but instead of blob URLs, write data: URIs into window.__resources

// First: list what we need
const files = await ls('trama');
log('trama files:', files);
const assets = await ls('trama/assets');
log('trama/assets:', assets);
const fonts = await ls('trama/fonts');
log('trama/fonts:', fonts);

// Build a fully-inline HTML — no blob: URLs, no fetch, all data: URIs and inline scripts.

async function readBinaryAsBase64(path) {
  const blob = await readFileBinary(path);
  const buf = await blob.arrayBuffer();
  const bytes = new Uint8Array(buf);
  let bin = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(bin);
}

async function dataUri(path, mime) {
  const b64 = await readBinaryAsBase64(path);
  return `data:${mime};base64,${b64}`;
}

// 1. Asset data URIs
const networkPatternData = 'data:image/svg+xml;base64,' + btoa(await readFile('trama/assets/network-pattern.svg'));
const tramaMarkData = 'data:image/svg+xml;base64,' + btoa(await readFile('trama/assets/trama-mark.svg'));
const tramaLogoData = await dataUri('trama/assets/trama-campus-logo.png', 'image/png');
const interFontData = await dataUri('trama/fonts/Inter-Variable.woff2', 'font/woff2');
const manropeFontData = await dataUri('trama/fonts/Manrope-Variable.woff2', 'font/woff2');

log('Asset sizes (chars):',
  'pattern=' + networkPatternData.length,
  'mark=' + tramaMarkData.length,
  'logo=' + tramaLogoData.length,
  'inter=' + interFontData.length,
  'manrope=' + manropeFontData.length);

// 2. CSS files — read, then replace url() refs and font urls
let colorsCss = await readFile('trama/colors_and_type.css');
colorsCss = colorsCss
  .replace(/url\(['"]?fonts\/Manrope-Variable\.woff2['"]?\)\s+format\(['"]woff2-variations['"]\)/g, `url(${manropeFontData}) format('woff2-variations')`)
  .replace(/url\(['"]?fonts\/Manrope-Variable\.woff2['"]?\)\s+format\(['"]woff2['"]\)/g, `url(${manropeFontData}) format('woff2')`)
  .replace(/url\(['"]?fonts\/Inter-Variable\.woff2['"]?\)\s+format\(['"]woff2-variations['"]\)/g, `url(${interFontData}) format('woff2-variations')`)
  .replace(/url\(['"]?fonts\/Inter-Variable\.woff2['"]?\)\s+format\(['"]woff2['"]\)/g, `url(${interFontData}) format('woff2')`);

const uiKitCss = await readFile('trama/ui_kit.css');
let tcStylesCss = await readFile('trama/tc-styles.css');
tcStylesCss = tcStylesCss.replace(/url\(['"]?assets\/network-pattern\.svg['"]?\)/g, `url(${networkPatternData})`);

// 3. JS/JSX files
const dataJs = await readFile('trama/data.js');
const tcDataJs = await readFile('trama/tc-data.js');
const designCanvasJsx = await readFile('trama/design-canvas.jsx');
const tweaksPanelJsx = await readFile('trama/tweaks-panel.jsx');
const tcComponentsJsx = await readFile('trama/tc-components.jsx');
const screensJsx = await readFile('trama/screens.jsx');

// 4. Read main index.html for the App script
const indexHtml = await readFile('trama/index.html');
// Extract the inline app script content (between the last <script type="text/babel" data-presets...> and </script>)
const appMatch = indexHtml.match(/<script type="text\/babel" data-presets="env,react">([\s\S]*?)<\/script>/);
if (!appMatch) throw new Error('Could not find App script in index.html');
let appJsx = appMatch[1];

// 5. Save resource paths to a global, since some code might reference window.__resources
const resourcesScript = `
window.__resources = {
  networkPattern: ${JSON.stringify(networkPatternData)},
  tramaLogoPng: ${JSON.stringify(tramaLogoData)},
  tramaMarkSvg: ${JSON.stringify(tramaMarkData)}
};
`;

// 6. The design-canvas tries to fetch state JSON. We need to make that fetch fail gracefully — already does with .catch in code? Let's check
const dcStateUsed = designCanvasJsx.match(/fetch\([^)]+\)([\s\S]{0,200})/);
log('Design canvas fetch context:', dcStateUsed && dcStateUsed[0].slice(0, 300));

// 7. Build the final HTML. NO external CDN — we need to inline React/Babel/Lucide.
// But sandbox can't fetch. Strategy: load these from the public CDN via <script src> in the bundled file.
// The user's CSP allows 'self' + 'unsafe-inline' for script-src. unpkg.com may be blocked too.
// Solution: keep the unpkg URLs since they were already in the original file — those are loaded
// directly (not as blobs) so CSP allowing 'self' won't allow them either!
// 
// BUT: the user's original site (yeisen.dev) had a CSP that blocked blob:. The CDN scripts may
// also be blocked unless 'self' covers them. Looking at the error:
//   "script-src 'self' 'unsafe-inline'" — this means ONLY scripts from same-origin OR inline
// So unpkg.com CDN won't load either.
// 
// We MUST inline React + Babel + Lucide. We can't fetch from sandbox. So we need to either:
//   (a) ask the user to include them somewhere we can read, or
//   (b) avoid them entirely (rewrite without React/Babel)
// 
// Option (c): use srcdoc trick — load the entire app inside an <iframe srcdoc>. The iframe has
// its own origin (data: or about:srcdoc) and inherits a different CSP. But CSP in srcdoc
// is inherited from the parent in some browsers.
//
// Best path: tell user to host the file directly without that CSP, OR I rewrite as plain JS without React.
// 
// Actually, looking again: 'script-src self' means the SAME ORIGIN. If yeisen.dev hosts the HTML,
// then yeisen.dev/static/react.js would work. But we don't control that.
//
// Cleanest: bundle React + Babel + Lucide as inline <script>...</script> blocks. unsafe-inline is
