// --- Modality-driven helpers ---------------------------------------------
// Order/filter the "reasons" list on a FeedCard by what matters in this modality.
function orderReasonsByModality(s, modality) {
  const academic = s.sharedCourses[0] && {
    icon: 'graduation-cap',
    html: `Comparten <b>${s.sharedCourses[0]}</b>${s.sharedCourses[1] ? ` y ${s.sharedCourses[1]}` : ''}.`,
  };
  const interests = s.sharedInterests[0] && {
    icon: 'microscope',
    html: `Coinciden en <b>${s.sharedInterests.slice(0,2).join(', ')}</b>.`,
  };
  const goals = s.sharedGoals[0] && {
    icon: 'compass',
    html: `Buscan: <b>${s.sharedGoals[0]}</b>.`,
  };
  const availability = s.availability && {
    icon: 'clock',
    html: `Disponible: <b>${s.availability}</b>.`,
  };
  if (modality === 'estudio') {
    return [academic, interests, goals].filter(Boolean).slice(0, 3);
  }
  if (modality === 'amistad') {
    return [interests, availability, goals].filter(Boolean).slice(0, 3);
  }
  // personal — quieter, more value-aligned, no academic noise
  return [interests, goals, availability].filter(Boolean).slice(0, 2);
}

// Score how relevant a student is to a given modality. Higher = show first.
function modalityRelevance(s, modality) {
  const courses = s.sharedCourses.length;
  const ints = s.sharedInterests.length;
  const goals = s.sharedGoals.length;
  const intentBoost = s.intent === modality ? 3 : 0;
  if (modality === 'estudio') return courses * 3 + ints + goals * 2 + intentBoost;
  if (modality === 'amistad') return ints * 3 + goals + courses * 0.3 + intentBoost;
  return goals * 3 + ints * 1.5 + intentBoost; // personal
}

// Sort full student list for the active modality.
function sortByModality(list, modality) {
  return [...list].sort((a, b) => modalityRelevance(b, modality) - modalityRelevance(a, modality));
}

